<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Policy\Allow\List;

use Override;
use Throwable;

use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\List\TemplateVersionListAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedListAllow
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(TemplateVersionListAllowDecision $proposal): TemplateVersionListAllowDecision
  {
    $this->logDebug("Check IsAuthenticatedListAllow Template version");
    $span = $this->startSpan("Check IsAuthenticatedListAllow Template version");
    try {
      $userContext = $this->context->getIdentity();
      if( $proposal->isAllowed()) {
        if( ! !$userContext->anonymous ) {
          $proposal->deny('Disabled if not IsAuthenticatedList');
        }      }
      return $proposal;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
